using System;using Ashfall.Core;using Ashfall.Modules.Pickups;using Ashfall.Integration.Playable.Consumables;using Ashfall.Integration.Playable.HandsWeapons;
class ConsumableLifeCases {
 sealed class Query:IInteractionQuery{public bool HasLineOfSight(string a,string b,Float3 c,Float3 d,float max){return true;}}
 sealed class Effects:IR23ConsumableEffects{internal readonly R23RoundState Round;internal Effects(R23RoundState actual){Round=actual;}public R23ConsumableVitals ReadVitals(){return new R23ConsumableVitals{Alive=Round.Health>0,Health=Round.Health,Shield=Round.Shield,Stamina=6,MaxStamina=6};}public bool TryApplyGain(float h,float s,bool stamina){return Round.ApplyPlayerGain(h,s);}}
 static int count;static void N(bool ok,string why){if(!ok)throw new Exception(why);count++;}static ActorFrame Frame(){return new ActorFrame{Allowed=true,HandEligible=true,OtherHandEligible=true,TransferSafe=true,Head=new Float3(0,1.65f,0),Hand=new Float3(0,1,.2f),Forward=new Float3(0,0,1),Anchor=new Float3(0,1.65f,.2f),HeadLocalAnchor=new Float3(0,0,.2f),ItemUpDot=0};}
 static void Main(){var q=new Query();var round=new R23RoundState(new string[0],q,true);round.ConfigureLocalMatchHealth("respawn",0,-1,100,0,0,10,1,0,1);var c=new R23ConsumableState(new Effects(round),q);N(c.Register("dose","soda",new Float3(0,1,.3f))&&c.Register("kept","soda",new Float3(0,1,.3f))&&c.Register("world","banana",new Float3(.4f,1,.4f)),"actual owned/world source identities");c.SetFrame(Frame());c.Advance(.02f);foreach(string id in new[]{"dose","kept"})N(c.Execute(PickupAction.Reserve,id).Accepted&&c.Execute(PickupAction.Collect,id).Accepted,"actual source pickup "+id);N(c.Execute(PickupAction.Equip,"dose").Accepted&&c.Execute(PickupAction.Open,"dose").Accepted&&c.Execute(PickupAction.Consume,"dose").Accepted,"actual source soda consumption starts real effect dose");N(c.PendingSoda==50&&c.Inspect("dose").Removed&&c.OwnedItems.Length==1,"actual pending dose and consumed world tombstone");N(c.Execute(PickupAction.Equip,"kept").Accepted,"actual retaining held stack member");round.ApplyDirectPlayerDamage(200);N(round.Health==0,"actual canonical player death");N(c.ResetActorLife()&&c.PendingSoda==0&&c.HeldId==null&&c.OwnedItems.Length==1&&c.Inspect("kept").Owner=="player","source actor death clears dose/gesture while retaining real owned item");N(c.Inspect("dose").Removed&&!c.Inspect("world").Removed&&c.Inspect("world").Owner==null&&c.Inspect("world").Position.X==.4f,"world tombstone/unowned source is not restored or moved");round.AdvanceLocalMatchHealth(1);N(round.TryRespawnLocalMatch()&&round.Shield==0,"actual zero-shield respawn");N(c.ResetActorLife(),"source respawn cancellation idempotent");for(int i=0;i<100;i++){c.SetFrame(Frame());c.Advance(.1f);}N(round.Shield==0&&c.PendingSoda==0&&c.OwnedItems.Length==1&&c.Inspect("dose").Removed,"no previous-life shield reward or world grant after actual respawn");Console.WriteLine(count+" actual canonical Health/soda cancellation/retained item/world-tombstone lifecycle checks PASS");}
